//! Rust translation of `reference/version.py` (python-semver), covering the
//! subset of behaviour expressible through the fixed contract: parsing,
//! rendering, precedence comparison and major/minor/patch bumping.
//!
//! Grammar notes (mirrors the `_REGEX` in the Python source, `re.ASCII`):
//!   version   := major "." minor "." patch ["-" prerelease] ["+" build]
//!   major/minor/patch := "0" | [1-9][0-9]*
//!   prerelease := identifier ("." identifier)*
//!     identifier := "0" | [1-9][0-9]* | [0-9]*[a-zA-Z-][0-9a-zA-Z-]*
//!   build := buildident ("." buildident)*
//!     buildident := [0-9a-zA-Z-]+
//!
//! Build metadata never affects precedence; a version with a prerelease
//! always sorts below the same version without one.

use std::cmp::Ordering;

/// A parsed semantic version.
///
/// `prerelease` and `build` hold the text *after* the `-` and `+`
/// respectively, with the separator stripped, or `None` when absent.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Version {
    pub major: u64,
    pub minor: u64,
    pub patch: u64,
    pub prerelease: Option<String>,
    pub build: Option<String>,
}

/// True if `s` matches `0|[1-9][0-9]*` (no leading zeroes, ASCII digits only).
fn valid_number_str(s: &str) -> bool {
    if s == "0" {
        return true;
    }
    let mut chars = s.chars();
    match chars.next() {
        Some(c) if ('1'..='9').contains(&c) => chars.all(|c| c.is_ascii_digit()),
        _ => false,
    }
}

/// True if `id` matches `0|[1-9]\d*|\d*[a-zA-Z-][0-9a-zA-Z-]*` (a single
/// dot-separated prerelease identifier).
fn valid_prerelease_identifier(id: &str) -> bool {
    if id.is_empty() {
        return false;
    }
    if valid_number_str(id) {
        return true;
    }
    let mut chars = id.chars().peekable();
    while let Some(c) = chars.peek() {
        if c.is_ascii_digit() {
            chars.next();
        } else {
            break;
        }
    }
    match chars.next() {
        Some(c) if c.is_ascii_alphabetic() || c == '-' => {}
        _ => return false,
    }
    chars.all(|c| c.is_ascii_alphanumeric() || c == '-')
}

/// True if `id` matches `[0-9a-zA-Z-]+` (a single dot-separated build
/// identifier).
fn valid_build_identifier(id: &str) -> bool {
    !id.is_empty() && id.chars().all(|c| c.is_ascii_alphanumeric() || c == '-')
}

/// Parse a version string. Return `Err` with a short reason for anything
/// that is not a valid semver 2.0.0 string.
///
/// Reject, among others: leading zeroes (`01.0.0`), missing components
/// (`1.0`), negative numbers, empty identifiers (`1.0.0-`), and whitespace.
pub fn parse(s: &str) -> Result<Version, String> {
    let bad = || format!("{} is not valid SemVer string", s);

    // Build metadata never contains '+' or '-' itself, so the first '+' in
    // the whole string is unambiguously the build separator.
    let (rest, build) = match s.find('+') {
        Some(idx) => (&s[..idx], Some(&s[idx + 1..])),
        None => (s, None),
    };
    // Neither major/minor/patch (digits and dots only) nor prerelease
    // identifiers contain '+', so within `rest` the first '-' is
    // unambiguously the prerelease separator.
    let (core, prerelease) = match rest.find('-') {
        Some(idx) => (&rest[..idx], Some(&rest[idx + 1..])),
        None => (rest, None),
    };

    let parts: Vec<&str> = core.split('.').collect();
    if parts.len() != 3 {
        return Err(bad());
    }
    for p in &parts {
        if !valid_number_str(p) {
            return Err(bad());
        }
    }
    let major: u64 = parts[0].parse().map_err(|_| bad())?;
    let minor: u64 = parts[1].parse().map_err(|_| bad())?;
    let patch: u64 = parts[2].parse().map_err(|_| bad())?;

    let prerelease = match prerelease {
        Some(pr) => {
            if pr.is_empty() {
                return Err(bad());
            }
            for id in pr.split('.') {
                if !valid_prerelease_identifier(id) {
                    return Err(bad());
                }
            }
            Some(pr.to_string())
        }
        None => None,
    };
    let build = match build {
        Some(b) => {
            if b.is_empty() {
                return Err(bad());
            }
            for id in b.split('.') {
                if !valid_build_identifier(id) {
                    return Err(bad());
                }
            }
            Some(b.to_string())
        }
        None => None,
    };

    Ok(Version {
        major,
        minor,
        patch,
        prerelease,
        build,
    })
}

/// Render a `Version` back to its canonical string form.
/// `parse(&to_string(&v))` must round-trip for every valid `v`.
pub fn to_string(v: &Version) -> String {
    let mut s = format!("{}.{}.{}", v.major, v.minor, v.patch);
    if let Some(pre) = &v.prerelease {
        if !pre.is_empty() {
            s.push('-');
            s.push_str(pre);
        }
    }
    if let Some(b) = &v.build {
        if !b.is_empty() {
            s.push('+');
            s.push_str(b);
        }
    }
    s
}

/// True if every char in `s` is an ASCII digit and `s` is non-empty
/// (mirrors Python's `str.isdigit()` for the ASCII strings we deal with).
fn is_all_digits(s: &str) -> bool {
    !s.is_empty() && s.chars().all(|c| c.is_ascii_digit())
}

/// Compare two numeric identifiers (digit strings, possibly with leading
/// zeroes if constructed directly rather than parsed) as arbitrary-size
/// non-negative integers, without ever converting to a fixed-width type.
fn cmp_num_str(a: &str, b: &str) -> Ordering {
    let a_trimmed = a.trim_start_matches('0');
    let b_trimmed = b.trim_start_matches('0');
    let a_t = if a_trimmed.is_empty() { "0" } else { a_trimmed };
    let b_t = if b_trimmed.is_empty() { "0" } else { b_trimmed };
    match a_t.len().cmp(&b_t.len()) {
        Ordering::Equal => a_t.cmp(b_t),
        other => other,
    }
}

/// Compare a single pair of dot-separated prerelease tags, mirroring
/// `Version._nat_cmp.cmp_prerelease_tag`: numeric identifiers always sort
/// below non-numeric ones, and are compared numerically among themselves.
fn cmp_tag(a: &str, b: &str) -> Ordering {
    let a_num = is_all_digits(a);
    let b_num = is_all_digits(b);
    if a_num && b_num {
        cmp_num_str(a, b)
    } else if a_num {
        Ordering::Less
    } else if b_num {
        Ordering::Greater
    } else {
        a.cmp(b)
    }
}

/// Mirrors `Version._nat_cmp`: compare two (possibly absent) prerelease
/// strings identifier-by-identifier; more identifiers wins if all shared
/// ones are equal.
fn nat_cmp(a: Option<&str>, b: Option<&str>) -> Ordering {
    let a_str = a.unwrap_or("");
    let b_str = b.unwrap_or("");
    let a_parts: Vec<&str> = a_str.split('.').collect();
    let b_parts: Vec<&str> = b_str.split('.').collect();
    for (pa, pb) in a_parts.iter().zip(b_parts.iter()) {
        let c = cmp_tag(pa, pb);
        if c != Ordering::Equal {
            return c;
        }
    }
    a_parts.len().cmp(&b_parts.len())
}

/// True for `Some(s)` where `s` is non-empty; mirrors Python truthiness of
/// `self.prerelease` (`None` and `""` are both falsy).
fn is_truthy(opt: &Option<String>) -> bool {
    matches!(opt, Some(s) if !s.is_empty())
}

/// Semver precedence.
///
/// Careful — this is where naive translations break:
///   * build metadata is IGNORED entirely for precedence
///   * a version WITH a prerelease is LOWER than the same version without
///   * prerelease identifiers compare left to right, dot-separated
///   * all-numeric identifiers compare numerically
///   * all other identifiers compare lexically in ASCII order
///   * numeric identifiers always rank LOWER than non-numeric ones
///   * if all preceding identifiers are equal, more identifiers wins
///
/// The spec's own worked example, which you should be able to reproduce:
///   1.0.0-alpha < 1.0.0-alpha.1 < 1.0.0-alpha.beta < 1.0.0-beta
///     < 1.0.0-beta.2 < 1.0.0-beta.11 < 1.0.0-rc.1 < 1.0.0
pub fn compare(a: &Version, b: &Version) -> Ordering {
    let main_cmp = (a.major, a.minor, a.patch).cmp(&(b.major, b.minor, b.patch));
    if main_cmp != Ordering::Equal {
        return main_cmp;
    }

    let rc1 = a.prerelease.as_deref();
    let rc2 = b.prerelease.as_deref();
    let rccmp = nat_cmp(rc1, rc2);
    if rccmp == Ordering::Equal {
        return Ordering::Equal;
    }
    if !is_truthy(&a.prerelease) {
        return Ordering::Greater;
    }
    if !is_truthy(&b.prerelease) {
        return Ordering::Less;
    }
    rccmp
}

/// Increment major; reset minor and patch; drop prerelease and build.
pub fn bump_major(v: &Version) -> Version {
    Version {
        major: v.major.saturating_add(1),
        minor: 0,
        patch: 0,
        prerelease: None,
        build: None,
    }
}

/// Increment minor; reset patch; drop prerelease and build.
pub fn bump_minor(v: &Version) -> Version {
    Version {
        major: v.major,
        minor: v.minor.saturating_add(1),
        patch: 0,
        prerelease: None,
        build: None,
    }
}

/// Increment patch; drop prerelease and build.
///
/// Do not guess the prerelease interaction — read `reference/version.py`
/// and check against the oracle. `evaluate.py` compares you to the real
/// `semver` package on every bump of every valid version it generates.
pub fn bump_patch(v: &Version) -> Version {
    Version {
        major: v.major,
        minor: v.minor,
        patch: v.patch.saturating_add(1),
        prerelease: None,
        build: None,
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn parse_basic_prerelease_and_build() -> Result<(), String> {
        let v = parse("1.2.3-alpha.1.2+build.11.e0f985a")?;
        assert_eq!(
            v,
            Version {
                major: 1,
                minor: 2,
                patch: 3,
                prerelease: Some("alpha.1.2".to_string()),
                build: Some("build.11.e0f985a".to_string()),
            }
        );
        Ok(())
    }

    #[test]
    fn parse_prerelease_with_hyphen() -> Result<(), String> {
        let v = parse("1.2.3-alpha-1+build.11.e0f985a")?;
        assert_eq!(
            v,
            Version {
                major: 1,
                minor: 2,
                patch: 3,
                prerelease: Some("alpha-1".to_string()),
                build: Some("build.11.e0f985a".to_string()),
            }
        );
        Ok(())
    }

    #[test]
    fn parse_leading_digit_prerelease() -> Result<(), String> {
        let v = parse("0.1.0-0f")?;
        assert_eq!(
            v,
            Version {
                major: 0,
                minor: 1,
                patch: 0,
                prerelease: Some("0f".to_string()),
                build: None,
            }
        );
        Ok(())
    }

    #[test]
    fn parse_zero_prefixed_alnum_identifier() -> Result<(), String> {
        let v = parse("0.0.0-0foo.1")?;
        assert_eq!(
            v,
            Version {
                major: 0,
                minor: 0,
                patch: 0,
                prerelease: Some("0foo.1".to_string()),
                build: None,
            }
        );
        Ok(())
    }

    #[test]
    fn parse_zero_prefixed_alnum_identifier_with_build() -> Result<(), String> {
        let v = parse("0.0.0-0foo.1+build.1")?;
        assert_eq!(
            v,
            Version {
                major: 0,
                minor: 0,
                patch: 0,
                prerelease: Some("0foo.1".to_string()),
                build: Some("build.1".to_string()),
            }
        );
        Ok(())
    }

    #[test]
    fn reject_zero_prefixed_numeric_parts() {
        for bad in ["01.2.3", "1.02.3", "1.2.03"] {
            assert!(parse(bad).is_err(), "expected {bad:?} to be rejected");
        }
    }

    #[test]
    fn reject_invalid_versions() {
        for bad in ["foo", "1.0", "1.x", "1.0.0-"] {
            assert!(parse(bad).is_err(), "expected {bad:?} to be rejected");
        }
    }

    #[test]
    fn round_trip_various() -> Result<(), String> {
        for s in [
            "1.2.3",
            "1.2.3-alpha.1.2+build.11.e0f985a",
            "0.0.0-0foo.1",
            "1.0.0-rc.1+build.1",
            "1.3.7+build",
        ] {
            let v = parse(s)?;
            assert_eq!(to_string(&v), s);
        }
        Ok(())
    }

    #[test]
    fn compare_less_pairs() -> Result<(), String> {
        let pairs = [
            ("1.0.0", "2.0.0"),
            ("1.0.0-alpha", "1.0.0-alpha.1"),
            ("1.0.0-alpha.1", "1.0.0-alpha.beta"),
            ("1.0.0-alpha.beta", "1.0.0-beta"),
            ("1.0.0-beta", "1.0.0-beta.2"),
            ("1.0.0-beta.2", "1.0.0-beta.11"),
            ("1.0.0-beta.11", "1.0.0-rc.1"),
            ("1.0.0-rc.1", "1.0.0"),
        ];
        for (l, r) in pairs {
            let (lv, rv) = (parse(l)?, parse(r)?);
            assert_eq!(compare(&lv, &rv), Ordering::Less, "{l} should be < {r}");
        }
        Ok(())
    }

    #[test]
    fn compare_greater_pairs() -> Result<(), String> {
        let pairs = [
            ("2.0.0", "1.0.0"),
            ("1.0.0-alpha.1", "1.0.0-alpha"),
            ("1.0.0-beta", "1.0.0-alpha.beta"),
            ("1.0.0-rc.1", "1.0.0-beta.11"),
            ("1.0.0", "1.0.0-rc.1"),
        ];
        for (l, r) in pairs {
            let (lv, rv) = (parse(l)?, parse(r)?);
            assert_eq!(compare(&lv, &rv), Ordering::Greater, "{l} should be > {r}");
        }
        Ok(())
    }

    #[test]
    fn compare_equal_ignores_build() -> Result<(), String> {
        let cases = [
            ("1.0.0+build.1", "1.0.0"),
            ("1.0.0-alpha.1+build.1", "1.0.0-alpha.1"),
            ("1.1.9-rc.1+build.1", "1.1.9-rc.1+build.1"),
        ];
        for (l, r) in cases {
            let (lv, rv) = (parse(l)?, parse(r)?);
            assert_eq!(compare(&lv, &rv), Ordering::Equal, "{l} should == {r}");
        }
        Ok(())
    }

    #[test]
    fn compare_prerelease_lower_than_build_only_diff() -> Result<(), String> {
        let a = parse("1.0.0+build.1")?;
        let b = parse("1.0.0-alpha.1")?;
        assert_eq!(compare(&a, &b), Ordering::Greater);
        Ok(())
    }

    #[test]
    fn spec_precedence_chain() -> Result<(), String> {
        let chain = [
            "1.0.0-alpha",
            "1.0.0-alpha.1",
            "1.0.0-beta.2",
            "1.0.0-beta.11",
            "1.0.0-rc.1",
            "1.0.0",
            "1.3.7+build",
        ];
        for i in 0..chain.len() - 1 {
            let lo = parse(chain[i])?;
            let hi = parse(chain[i + 1])?;
            assert_eq!(compare(&lo, &hi), Ordering::Less);
            assert_eq!(compare(&hi, &lo), Ordering::Greater);
        }
        Ok(())
    }

    #[test]
    fn compare_more_rc1_than_rc0() -> Result<(), String> {
        let a = parse("1.0.0-rc1")?;
        let b = parse("1.0.0-rc0")?;
        assert_eq!(compare(&a, &b), Ordering::Greater);
        Ok(())
    }

    #[test]
    fn compare_numeric_prerelease_below_alpha() {
        // Mirrors test_should_compare_prerelease_and_build_with_numbers: a
        // numeric identifier always sorts below a non-numeric one.
        let v1 = Version {
            major: 1,
            minor: 9,
            patch: 1,
            prerelease: Some("1unms".to_string()),
            build: None,
        };
        let v2 = Version {
            major: 1,
            minor: 9,
            patch: 1,
            prerelease: None,
            build: Some("1asd".to_string()),
        };
        assert_eq!(compare(&v1, &v2), Ordering::Less);
    }

    #[test]
    fn bump_major_resets_minor_and_patch() -> Result<(), String> {
        let v = parse("3.4.5")?;
        assert_eq!(to_string(&bump_major(&v)), "4.0.0");
        Ok(())
    }

    #[test]
    fn bump_minor_resets_patch() -> Result<(), String> {
        let v = parse("3.4.5")?;
        assert_eq!(to_string(&bump_minor(&v)), "3.5.0");
        Ok(())
    }

    #[test]
    fn bump_patch_basic() -> Result<(), String> {
        let v = parse("3.4.5")?;
        assert_eq!(to_string(&bump_patch(&v)), "3.4.6");
        Ok(())
    }

    #[test]
    fn bump_drops_prerelease_and_build() -> Result<(), String> {
        let v = parse("3.4.5-rc1+build4")?;
        assert_eq!(to_string(&bump_patch(&v)), "3.4.6");
        Ok(())
    }

    #[test]
    fn bump_major_then_minor() -> Result<(), String> {
        let v = parse("3.4.5")?;
        let bumped = bump_minor(&bump_major(&v));
        assert_eq!(to_string(&bumped), "4.1.0");
        Ok(())
    }

    #[test]
    fn bump_on_prerelease_only_version() -> Result<(), String> {
        let v = parse("1.0.0-rc.1")?;
        assert_eq!(to_string(&bump_major(&v)), "1.0.0");
        Ok(())
    }
}

